import {esc,num} from './ui.mjs';
import {monthIndex,monthName} from './pdp-model.mjs?v=20261102-pdp1';
const finite=v=>typeof v==='number'&&Number.isFinite(v);
export function pdpPlot({title,series,bands=[],verticals=[],scale='log',annotation=[]}){const all=series.flatMap(s=>s.rows.map(r=>({month:r.month,value:r[s.key??'value']}))),bandValues=bands.flatMap(b=>b.rows.flatMap(r=>[r[b.low],r[b.high]])),months=all.filter(r=>r.month).map(r=>monthIndex(r.month)),values=[...all.map(r=>r.value),...bandValues].filter(v=>finite(v)&&(scale!=='log'||v>0));if(!months.length||!values.length)return '<div class="empty">当前范围没有可绘制的有效产量</div>';const w=1120,h=432,l=90,r=30,t=64,b=52,xmin=Math.min(...months),xmax=Math.max(...months),convert=v=>scale==='log'?Math.log10(v):v;let ymin=Math.min(...values.map(convert)),ymax=Math.max(...values.map(convert));if(scale==='linear')ymin=Math.min(0,ymin);if(ymin===ymax)ymax=ymin+(scale==='log'?.2:1);const pad=(ymax-ymin)*.13;ymin-=scale==='log'?pad:0;ymax+=pad;const x=m=>l+(monthIndex(m)-xmin)/Math.max(1,xmax-xmin)*(w-l-r),y=v=>t+(ymax-convert(v))/(ymax-ymin)*(h-t-b),line=rows=>{let d='',active=false;for(const p of rows){if(!finite(p.value)||scale==='log'&&p.value<=0){active=false;continue;}d+=(active?'L':'M')+x(p.month).toFixed(2)+','+y(p.value).toFixed(2)+' ';active=true;}return d;},path=s=>line(s.rows.map(r=>({month:r.month,value:r[s.key??'value']})));const unique=new Map();for(const m of months)unique.set(m,true);const ticks=[...unique.keys()].sort((a,b)=>a-b).filter((v,i,a)=>i===0||i===a.length-1||v%12===0||a.length<20&&v%3===0);const grid=Array.from({length:9},(_,i)=>{const p=ymin+(ymax-ymin)*i/8,v=scale==='log'?10**p:p,yy=t+(8-i)/8*(h-t-b);return `<line x1="${l}" x2="${w-r}" y1="${yy}" y2="${yy}" stroke="${i%2?'#efefed':'#dadbd7'}"/><text x="${l-12}" y="${yy+4}" text-anchor="end">${num(v,0)}</text>`;}).join('');const shades=bands.map(b=>{const segments=[];let current=[];for(const r of b.rows){if(finite(r[b.low])&&finite(r[b.high])&&(scale!=='log'||r[b.low]>0)){current.push(r);}else if(current.length){segments.push(current);current=[];}}if(current.length)segments.push(current);return segments.map(a=>`<path d="${a.map((r,i)=>(i?'L':'M')+x(r.month)+','+y(r[b.high])).join(' ')} ${[...a].reverse().map(r=>'L'+x(r.month)+','+y(r[b.low])).join(' ')} Z" fill="${b.color}" fill-opacity="${b.opacity??.13}"/>`).join('');}).join('');const marks=series.filter(s=>s.markers).map(s=>s.rows.filter(r=>finite(r[s.key??'value'])).map(r=>{const v=r[s.key??'value'],yy=scale==='log'&&v<=0?h-b:y(v),c=r.level==='红'?'#bd2938':r.level==='黄'?'#c28a26':s.color;return `<g><title>${esc(r.month)}：${num(v,1)}吨/月${r.deviation!==undefined&&r.deviation!==null?'，相对基准'+num(r.deviation)+'%':''}${r.reason?'；'+esc(r.reason):''}</title><rect x="${x(r.month)-3.5}" y="${yy-3.5}" width="7" height="7" fill="${c}"/>${['红','黄'].includes(r.level)?`<circle cx="${x(r.month)}" cy="${yy}" r="7" fill="none" stroke="${c}"/>`:''}</g>`;}).join('')).join('');const vlines=verticals.map(v=>{const xx=l+(monthIndex(v.month)+.5-xmin)/Math.max(1,xmax-xmin)*(w-l-r);return `<line x1="${xx}" x2="${xx}" y1="${t}" y2="${h-b}" stroke="${v.color??'#2a8ac1'}" stroke-width="1.5" ${v.dash?'stroke-dasharray="5 4"':''}/><text x="${Math.min(w-r-130,Math.max(l+5,xx+6))}" y="${t+14}" fill="${v.color??'#2a8ac1'}">${esc(v.label)}</text>`;}).join('');const legend=[...series.map(s=>({name:s.name,color:s.color,dash:s.dash})),...bands.map(s=>({name:s.name,color:s.color,band:true}))],legendHeight=Math.ceil(legend.length/3)*26+18,legendSvg=legend.map((s,i)=>{const xx=90+(i%3)*335,yy=h+22+Math.floor(i/3)*26;return `<line x1="${xx}" x2="${xx+20}" y1="${yy-4}" y2="${yy-4}" stroke="${s.color}" stroke-width="${s.band?8:2}" ${s.dash?'stroke-dasharray="6 4"':''} ${s.band?'opacity=".4"':''}/><text x="${xx+27}" y="${yy}" style="font-size:10px">${esc(s.name)}</text>`;}).join('');const info=annotation.length?`<rect x="${w-330}" y="${t+28}" width="285" height="${annotation.length*20+16}" rx="8" fill="#ffffffe8" stroke="#6e92ba" stroke-dasharray="5 4"/>${annotation.map((s,i)=>`<text x="${w-315}" y="${t+53+i*20}" fill="#35627b">${esc(s)}</text>`).join('')}`:'';return `<div class="pdp-svg"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h+legendHeight}" role="img" aria-label="${esc(title)}；纵轴吨/月，${scale==='log'?'半对数':'线性'}坐标"><style>text{font:12px 'Microsoft YaHei','PingFang SC',sans-serif;fill:#5d6669}</style><rect width="${w}" height="${h+legendHeight}" fill="white"/><text x="${l}" y="22" style="font-weight:600;font-size:15px">${esc(title)}</text><text x="${l}" y="45">月产油 / 吨（月历天、已有在产井口径） · ${scale==='log'?'半对数':'线性'}轴</text>${grid}${ticks.map(i=>`<line x1="${x(monthName(i))}" x2="${x(monthName(i))}" y1="${t}" y2="${h-b}" stroke="#e5e5e1"/><text x="${x(monthName(i))}" y="${h-26}" text-anchor="middle">${esc(monthName(i))}</text>`).join('')}${shades}${vlines}${series.map(s=>`<path d="${path(s)}" fill="none" stroke="${s.color}" stroke-width="${s.width??2}" ${s.dash?'stroke-dasharray="7 5"':''}/>`).join('')}${marks}${info}<text x="${w/2}" y="${h-5}" text-anchor="middle">生产月份；竖线区分冻结日/预测起点</text>${legendSvg}</svg></div>`;}
export function baselineFigure(run,scale='log'){const history=run.history.slice(-24);return pdpPlot({title:'图1：上年末冻结预测与当年月产油偏差预警',scale,series:[{name:'历史实测/生成月油',color:'#2b873c',rows:history,key:'oil_tonnes'},{name:run.baseYear+'年末冻结预测',color:'#2b873c',rows:run.baseline.filter(r=>r.month.startsWith(String(run.baseYear+1)+'-')),key:'prediction',dash:true},{name:'当年月油（红圈=预警）',color:'#c52ba7',rows:run.current,key:'actual',markers:true}],bands:[{name:'冻结基准95%单月预测区间（如可用）',rows:run.baseline.filter(r=>r.month.startsWith(String(run.baseYear+1)+'-')),low:'pi_low',high:'pi_high',color:'#63b86d',opacity:.13}],verticals:[{month:run.freezeMonth,label:run.freezeDate+' 冻结'}],annotation:['基准：'+run.baselineSource,'有效年递减率：'+(run.baselineModel?num(run.baselineModel.annualDecline*100)+'%':'原计划模型未知'),'当年累计偏差：'+num(run.metrics.cumulativeDeviation)+'%','来源：'+(run.source.includes('生成')?'生成场景，非现场实测':'用户上传，需核实')]});}
export function forecastFigure(run,scale='log'){const past=run.observed.slice(-12),old=[...new Map([...run.baseline,...run.forecast.filter(r=>r.baseline!==null).map(r=>({month:r.month,prediction:r.baseline}))].map(r=>[r.month,r])).values()].filter(r=>r.month>=past[0]?.month&&r.month<=run.forecast.at(-1).month).sort((a,b)=>a.month.localeCompare(b.month)),scenario=run.gainPct!==0||run.plannedWells!==run.latest.active_wells;return pdpPlot({title:'图2：专家研判后的后续预测与置信区间',scale,series:[{name:'最近月油观测',color:'#424c50',rows:past,key:'oil_tonnes',markers:true},{name:'原冻结基准（不改写）',color:'#2b873c',rows:old,key:'prediction',dash:true},{name:'更新模型：维持最新在产井条件',color:'#286ca6',rows:run.forecast,key:'prediction'},...(scenario?[{name:'专家输入的措施条件情景（非效果承诺）',color:'#d8882d',rows:run.forecast,key:'scenario',dash:true}]:[])],bands:[{name:'更新模型95%单月预测区间 PI',rows:run.forecast,low:'pi_low',high:'pi_high',color:'#7bb2dc',opacity:.15},{name:'更新模型95%均值置信区间 CI',rows:run.forecast,low:'ci_low',high:'ci_high',color:'#286ca6',opacity:.22},...(scenario?[{name:'措施情景95%条件PI',rows:run.forecast,low:'scenario_pi_low',high:'scenario_pi_high',color:'#e9af6a',opacity:.09},{name:'措施情景95%条件CI',rows:run.forecast,low:'scenario_ci_low',high:'scenario_ci_high',color:'#d8882d',opacity:.15}]:[])],verticals:[{month:run.forecastOrigin,label:run.forecastOrigin+' 末 / 后续预测'}],annotation:['更新拟合：'+run.updatedModel.firstMonth+' 至 '+run.updatedModel.lastMonth,'有效月数：'+run.updatedModel.n+'；Bootstrap='+run.bootstrap,'维持井数：'+run.latest.active_wells+'；情景井数：'+run.plannedWells,'95%为点位条件区间，非PDP认证概率']});}
export function contextFigure(run){const ref=run.December;if(!ref)return '<div class="tiny">缺少年末监测基准，暂不绘制归一化对照。</div>';const rows=run.observed.filter(r=>r.month>=run.history.slice(-12)[0]?.month),specs=[{k:'perwell',name:'单井月油 / 基准月=100',color:'#c52ba7',base:ref.active_wells>0?ref.oil_tonnes/ref.active_wells:null,read:r=>r.active_wells>0?r.oil_tonnes/r.active_wells:null},{name:'产水量 / 基准月=100',color:'#2452bf',base:ref.water_m3,read:r=>r.water_m3},{name:'在产井数 / 基准月=100',color:'#dfb42e',base:ref.active_wells,read:r=>r.active_wells}];return pdpPlot({title:'参考图风格配套监测（归一化）',scale:'linear',series:specs.map(s=>({name:s.name,color:s.color,rows:rows.map(r=>({month:r.month,value:s.base>0&&typeof s.read(r)==='number'?100*s.read(r)/s.base:null}))})),annotation:[]}).replace('月产油 / 吨（月历天、已有在产井口径） · 线性轴','监测指数 / 年末基准月=100（各变量独立归一化）').replace('纵轴吨/月，线性坐标','纵轴基准指数，线性坐标').replace('生产月份；竖线区分冻结日/预测起点','生产月份；各监测指标独立归一化比较');}
export function svgOnly(markup){const match=markup.match(/<svg[\s\S]*?<\/svg>/);if(!match)throw Error('暂无可导出图形');return match[0];}
